#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <json-c/json.h>
#include <sys/stat.h>
#include <unistd.h>

#define MAX_URL_LEN 2048
#define MAX_PATH_LEN 512
#define MODEL_REGISTRY "https://models.internal.corp/v2/"
#define ALLOWED_WEIGHTS_HOST "weights.internal.corp"

typedef struct {
    char model_name[256];
    char model_version[64];
    char weights_hash[65];
    int  use_cached;
} InferenceConfig;

typedef struct {
    char *data;
    size_t size;
} MemBuffer;

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t total = size * nmemb;
    MemBuffer *buf = (MemBuffer *)userp;
    char *tmp = realloc(buf->data, buf->size + total + 1);
    if (!tmp) return 0;
    buf->data = tmp;
    memcpy(buf->data + buf->size, contents, total);
    buf->size += total;
    buf->data[buf->size] = '\0';
    return total;
}

static int validate_model_name(const char *name) {
    /* Only allow alphanumeric, hyphens, underscores, dots */
    for (int i = 0; name[i]; i++) {
        char c = name[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.')) {
            return 0;
        }
    }
    return 1;
}

static int validate_weights_url(const char *url) {
    /* Only allow HTTPS URLs pointing to our trusted weights host */
    if (strncmp(url, "https://", 8) != 0) return 0;

    const char *host_start = url + 8;
    const char *host_end = strchr(host_start, '/');
    if (!host_end) host_end = host_start + strlen(host_start);

    /* Strip port if present */
    const char *port_sep = memchr(host_start, ':', host_end - host_start);
    size_t host_len = port_sep ? (size_t)(port_sep - host_start) : (size_t)(host_end - host_start);

    if (host_len != strlen(ALLOWED_WEIGHTS_HOST)) return 0;
    if (strncmp(host_start, ALLOWED_WEIGHTS_HOST, host_len) != 0) return 0;

    /* Reject URLs with @ (credential injection), encoded chars in host */
    for (const char *p = url + 8; p < host_end; p++) {
        if (*p == '@' || *p == '%') return 0;
    }

    return 1;
}

static int resolve_model_endpoint(const char *registry_base, const char *model_name,
                                   const char *version, char *out_url, size_t out_len) {
    /* Fetch model manifest from registry to get actual weights URL */
    char manifest_url[MAX_URL_LEN];
    snprintf(manifest_url, sizeof(manifest_url), "%s%s/manifests/%s",
             registry_base, model_name, version);

    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    MemBuffer response = {0};
    curl_easy_setopt(curl, CURLOPT_URL, manifest_url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 0L);

    CURLcode res = curl_easy_perform(curl);
    curl_easy_cleanup(curl);

    if (res != CURLE_OK || !response.data) {
        free(response.data);
        return -1;
    }

    /* Parse manifest JSON to extract weights_url */
    struct json_object *root = json_tokener_parse(response.data);
    free(response.data);
    if (!root) return -1;

    struct json_object *weights_obj;
    if (!json_object_object_get_ex(root, "weights_url", &weights_obj)) {
        json_object_put(root);
        return -1;
    }

    const char *weights_url = json_object_get_string(weights_obj);
    if (!weights_url || strlen(weights_url) >= out_len) {
        json_object_put(root);
        return -1;
    }

    /* Validate that the resolved URL points to our trusted weights host */
    if (!validate_weights_url(weights_url)) {
        fprintf(stderr, "Rejected untrusted weights URL: %s\n", weights_url);
        json_object_put(root);
        return -1;
    }

    strncpy(out_url, weights_url, out_len - 1);
    out_url[out_len - 1] = '\0';
    json_object_put(root);
    return 0;
}

static int fetch_model_weights(const char *url, const char *dest_path) {
    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    FILE *fp = fopen(dest_path, "wb");
    if (!fp) { curl_easy_cleanup(curl); return -1; }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 60L);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 0L);
    curl_easy_setopt(curl, CURLOPT_PROTOCOLS, CURLPROTO_HTTPS);

    CURLcode res = curl_easy_perform(curl);
    fclose(fp);
    curl_easy_cleanup(curl);
    return (res == CURLE_OK) ? 0 : -1;
}

int parse_inference_request(const char *json_body, InferenceConfig *config) {
    struct json_object *root = json_tokener_parse(json_body);
    if (!root) return -1;

    struct json_object *name_obj, *ver_obj, *hash_obj, *cache_obj;

    if (!json_object_object_get_ex(root, "model", &name_obj)) goto fail;
    if (!json_object_object_get_ex(root, "version", &ver_obj)) goto fail;

    const char *name = json_object_get_string(name_obj);
    const char *ver = json_object_get_string(ver_obj);

    if (!name || !ver || !validate_model_name(name)) goto fail;
    if (strlen(name) >= sizeof(config->model_name)) goto fail;
    if (strlen(ver) >= sizeof(config->model_version)) goto fail;

    /* Version must also be validated */
    if (!validate_model_name(ver)) goto fail;

    strncpy(config->model_name, name, sizeof(config->model_name) - 1);
    strncpy(config->model_version, ver, sizeof(config->model_version) - 1);

    config->use_cached = 1;
    if (json_object_object_get_ex(root, "use_cached", &cache_obj)) {
        config->use_cached = json_object_get_boolean(cache_obj);
    }

    memset(config->weights_hash, 0, sizeof(config->weights_hash));
    if (json_object_object_get_ex(root, "weights_hash", &hash_obj)) {
        const char *h = json_object_get_string(hash_obj);
        if (h && strlen(h) == 64) strncpy(config->weights_hash, h, 64);
    }

    json_object_put(root);
    return 0;
fail:
    json_object_put(root);
    return -1;
}

int handle_inference(const char *request_json) {
    InferenceConfig config;
    memset(&config, 0, sizeof(config));

    if (parse_inference_request(request_json, &config) != 0) {
        fprintf(stderr, "Invalid request\n");
        return -1;
    }

    char cache_path[MAX_PATH_LEN];
    snprintf(cache_path, sizeof(cache_path), "/var/cache/models/%s_%s.bin",
             config.model_name, config.model_version);

    struct stat st;
    if (config.use_cached && stat(cache_path, &st) == 0) {
        printf("Using cached model: %s\n", cache_path);
        /* proceed with inference using cached weights */
        return 0;
    }

    /* Resolve the actual download URL from the model registry */
    char resolved_url[MAX_URL_LEN];
    if (resolve_model_endpoint(MODEL_REGISTRY, config.model_name,
                                config.model_version, resolved_url, sizeof(resolved_url)) != 0) {
        fprintf(stderr, "Failed to resolve model endpoint\n");
        return -1;
    }

    /* Download weights from validated URL */
    if (fetch_model_weights(resolved_url, cache_path) != 0) {
        fprintf(stderr, "Failed to fetch model weights\n");
        unlink(cache_path);
        return -1;
    }

    printf("Model loaded, running inference...\n");
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <request.json>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "r");
    if (!f) { perror("fopen"); return 1; }

    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    if (len <= 0 || len > 65536) { fclose(f); return 1; }
    fseek(f, 0, SEEK_SET);

    char *buf = malloc(len + 1);
    if (!buf) { fclose(f); return 1; }
    fread(buf, 1, len, f);
    buf[len] = '\0';
    fclose(f);

    int ret = handle_inference(buf);
    free(buf);
    return ret;
}
